import assert from 'node:assert/strict';
import { readFile,writeFile } from 'node:fs/promises';
import { FractalMindSDK } from '/Users/yubing/Workspace/fractalmind-labs/fractalmind-os/protocols/fractalmind-protocol/sdk/dist/index.js';
const input=JSON.parse(await readFile('/tmp/fm-mixed-origins-app-envd-r1.json.progress.json','utf8'));
const deployment=JSON.parse(await readFile('/tmp/fm-mixed-origin-deployment-r1.json','utf8'));
const sdk=new FractalMindSDK({...deployment,network:'localnet',fullnodeUrl:'http://127.0.0.1:29000'});
const source=input.transactions.at(-1);
const type=await sdk.client.coreType('node_execution','CommandExecution');
const created=source.createdObjects.filter(o=>o.type===type && o.outputState==='ObjectWrite');
assert.equal(created.length,1);
let receiptStatus;
try {
 const receipt=await sdk.client.client.core.getTransaction({digest:source.digest,include:{effects:true}});
 assert.equal(receipt.$kind,'Transaction');assert.equal(receipt.Transaction.digest,source.digest);assert.equal(receipt.Transaction.status.success,true);
 receiptStatus={status:'confirmed',digest:source.digest};
} catch(error) {
 if(error?.reason!=='notFound' || error.digest!==source.digest)throw error;
 receiptStatus={status:'unknown',digest:source.digest,reason:'original_transaction_not_found'};
}
const run=await sdk.nodeExecution.getExecution(created[0].id);
assert.equal(run.id,created[0].id);
assert.equal(run.state,0);
assert.equal(run.result_record,null);
const budget=await sdk.nodeExecution.getBudget(run.capability_id);
assert.equal(budget.spent,0n);assert.equal(budget.reserved,0n);
const human=await sdk.identity.getHuman(input.state.humanId);
assert.equal(human.generation,'1');
const member=await sdk.host.getMembership(input.state.membershipId);
const output={checkedAt:new Date().toISOString(),broadcasts:0,sourceDigest:source.digest,receiptStatus,run,budget,humanId:human.id,generation:human.generation,membershipId:member.id,memberRevoked:member.revoked,limits:{noNewSigner:true,noPrivateKeysOrRecoveryCodes:true,originalRunNotReplayed:true,originalCleanupOnly:input.limits.cleanupConfirmed}};
await writeFile('/tmp/fm-mixed-origins-r1-original-read-r3.json',JSON.stringify(output,(_,v)=>typeof v==='bigint'?v.toString():v,2)+'\n',{flag:'wx'});
process.stdout.write(JSON.stringify({broadcasts:0,receiptStatus,executionId:run.id,state:run.state,budget,generation:human.generation,memberRevoked:member.revoked},(_,v)=>typeof v==='bigint'?v.toString():v)+'\n');
